SET DEFINE OFF
-- Synthetic source database for the financial-services demo (Deposit balances and average daily balance data product)
-- Dialect: oracle. Generated by ADEF; all values are synthetic.

-- Schema-only accounts: they own the tables and cannot log in (no passwords).
CREATE USER CBS NO AUTHENTICATION QUOTA UNLIMITED ON USERS;

-- Customers
CREATE TABLE CBS.CUSTOMER (
    CUSTOMER_ID                VARCHAR2(20)       NOT NULL,
    FULL_NAME                  VARCHAR2(200)     ,
    NATIONAL_ID                VARCHAR2(20)      ,
    DATE_OF_BIRTH              DATE              ,
    SEGMENT                    VARCHAR2(20)      ,
    KYC_STATUS                 VARCHAR2(10)      ,
    ONBOARD_DATE               DATE              ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_CUSTOMER PRIMARY KEY (CUSTOMER_ID)
);

COMMENT ON COLUMN CBS.CUSTOMER.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Deposit accounts
CREATE TABLE CBS.ACCOUNT (
    ACCOUNT_ID                 VARCHAR2(20)       NOT NULL,
    CUSTOMER_ID                VARCHAR2(20)      ,
    PRODUCT_CODE               VARCHAR2(10)      ,
    BRANCH_CODE                VARCHAR2(8)       ,
    OPEN_DATE                  DATE              ,
    STATUS                     VARCHAR2(10)      ,
    CURRENCY                   VARCHAR2(3)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_ACCOUNT PRIMARY KEY (ACCOUNT_ID)
);

COMMENT ON COLUMN CBS.ACCOUNT.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Deposit products
CREATE TABLE CBS.PRODUCT (
    PRODUCT_CODE               VARCHAR2(10)       NOT NULL,
    PRODUCT_NAME               VARCHAR2(100)     ,
    PRODUCT_TYPE               VARCHAR2(20)      ,
    INTEREST_RATE              NUMBER(7,4)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_PRODUCT PRIMARY KEY (PRODUCT_CODE)
);

COMMENT ON COLUMN CBS.PRODUCT.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- End-of-day balances
CREATE TABLE CBS.DAILY_BALANCE (
    ACCOUNT_ID                 VARCHAR2(20)       NOT NULL,
    BALANCE_DATE               DATE               NOT NULL,
    LEDGER_BALANCE             NUMBER(18,2)      ,
    AVAILABLE_BALANCE          NUMBER(18,2)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_DAILY_BALANCE PRIMARY KEY (ACCOUNT_ID, BALANCE_DATE)
);

COMMENT ON COLUMN CBS.DAILY_BALANCE.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';
